/**
 * Purge of FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - Non-ERROR logs (DEBUG, INFO, blank Level__c, etc.) are deleted once created more than 30 days ago.
 *  - ERROR logs are kept until created more than 180 days ago.
 *
 * execute(SchedulableContext) purges synchronously in bounded chunks, staying within
 * the per-transaction DML row limit. The class also implements Database.Batchable so
 * that very large backlogs can be cleared with Database.executeBatch(new LogPurgeJob()).
 *
 * Runs in system context (without sharing) so that every log is purged regardless
 * of the running user's sharing or record visibility.
 */
public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_EXPRESSION = '0 0 2 * * ?';
    public static final Integer NON_ERROR_RETENTION_DAYS = 30;
    public static final Integer ERROR_RETENTION_DAYS = 180;
    public static final Integer BATCH_SIZE = 2000;
    // Stays below the 10,000 DML rows limit for a single synchronous transaction.
    public static final Integer MAX_SYNC_DELETE_ATTEMPTS = 8000;

    public LogPurgeJob() {
    }

    /**
     * Schedulable entry point: purges eligible logs in this transaction.
     */
    public void execute(SchedulableContext sc) {
        purgeEligibleLogs();
    }

    /**
     * Schedules the purge to run every day at 02:00 under JOB_NAME.
     * Any previously scheduled job with the same name is aborted first so that
     * re-running setup does not fail on duplicate job names.
     */
    public static Id scheduleNightly() {
        for (CronTrigger ct : [
            SELECT Id
            FROM CronTrigger
            WHERE CronJobDetail.Name = :JOB_NAME
        ]) {
            System.abortJob(ct.Id);
        }
        return System.schedule(JOB_NAME, CRON_EXPRESSION, new LogPurgeJob());
    }

    /**
     * Deletes eligible logs in chunks until none remain or the synchronous
     * attempt cap is reached. Returns the number of records successfully deleted.
     * Stops early if a whole chunk fails, to avoid re-selecting the same
     * undeletable records forever.
     */
    public static Integer purgeEligibleLogs() {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        Integer attempted = 0;
        Integer deleted = 0;

        while (attempted < MAX_SYNC_DELETE_ATTEMPTS) {
            List<FB_Integration_Log__c> chunk = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :nonErrorCutoff
                        AND (Level__c = null OR Level__c != 'ERROR'))
                   OR (CreatedDate < :errorCutoff
                        AND Level__c = 'ERROR')
                LIMIT :BATCH_SIZE
            ];
            if (chunk.isEmpty()) {
                break;
            }

            attempted += chunk.size();
            Integer succeededInChunk = deleteChunk(chunk);
            deleted += succeededInChunk;

            if (succeededInChunk == 0) {
                break;
            }
        }
        return deleted;
    }

    /**
     * Deletes one chunk with partial success allowed, so one undeletable record
     * does not block the rest. Returns the number of successful deletes.
     */
    private static Integer deleteChunk(List<FB_Integration_Log__c> scope) {
        if (scope == null || scope.isEmpty()) {
            return 0;
        }
        Integer succeeded = 0;
        List<Database.DeleteResult> results = Database.delete(scope, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                succeeded++;
            } else {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'LogPurgeJob failed to delete ' + scope[i].Id + ': '
                        + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
        return succeeded;
    }

    /**
     * Batch start: selects logs eligible for deletion.
     * Blank Level__c is handled explicitly because "!= 'ERROR'" does not match nulls in SOQL.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff
                    AND (Level__c = null OR Level__c != 'ERROR'))
               OR (CreatedDate < :errorCutoff
                    AND Level__c = 'ERROR')
        ]);
    }

    /**
     * Batch execute: deletes one scope chunk.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        deleteChunk(scope);
    }

    /**
     * Batch finish: no post-processing required.
     */
    public void finish(Database.BatchableContext bc) {
    }
}
