    // Helpers
    // ---------------------------------------------------------------

    private static Opportunity buildOpportunity(
        Id oppId,
        String name,
        Id ownerId,
        Decimal amount,
        Date closeDate,
        String stageName
    ) {
        return new Opportunity(
            Id = oppId,
