/**
 * Publishes Deal_Stage_Change__e platform events (publish after commit) for a
 * list of Opportunities.
 *
 * All events are built in memory and published with a single EventBus.publish
 * call. That counts as one DML statement, which keeps a 200-record trigger
 * batch under the 150 DML statement governor limit. EventBus.publish returns
 * one SaveResult per event in the same order as the input list, so
 * result[i] corresponds to opportunities[i].
 */
public with sharing class DealEventPublisher {

    /** Length limit of Deal_Stage_Change__e.Stage__c (Text 40). */
    private static final Integer STAGE_MAX_LENGTH = 40;

    /**
     * Publishes one Deal_Stage_Change__e event per opportunity.
     *
     * @param opportunities Opportunities whose stage changed (up to 200 from a trigger).
     * @return SaveResults in the same order as the input list. An empty or null
     *         input publishes nothing and returns an empty list.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>(opportunities.size());
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = String.valueOf(opp.Id),
                Stage__c          = truncateStage(opp.StageName),
                Amount__c         = opp.Amount
            ));
        }

        // One DML statement for the whole batch; results are index-aligned with 'events'.
        results.addAll(EventBus.publish(events));
        return results;
    }

    /**
     * Ensures the stage name fits in Stage__c (Text 40).
     */
    private static String truncateStage(String stageName) {
        if (stageName == null || stageName.length() <= STAGE_MAX_LENGTH) {
            return stageName;
        }
        return stageName.substring(0, STAGE_MAX_LENGTH);
    }
}
