```apex
/**
 * Trigger Action (Trigger Actions Framework 0.3.4) that prevents two Contacts on the same
 * Account from sharing an email address (case-insensitive).
 *
 * Registered via Trigger_Action__mdt for Contact, before insert and before update.
 *
 * - Contacts without an AccountId or Email are not checked.
 * - On update, only records whose Email or AccountId changed are checked. Unchanged records
 *   still hold their (account, email) slot but are never rejected themselves.
 * - Within one save, the first record that claims an (account, email) pair is accepted and
 *   every later conflicting record is rejected.
 * - A record never conflicts with itself; records in the current save are compared using
 *   their in-memory values, not their stored values.
 * - Errors are added per record, so valid records in the same save are unaffected.
 * - At most one SOQL query per execution, and none when nothing needs checking.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, new Map<Id, Contact>());
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (triggerOld != null) {
            for (SObject so : triggerOld) {
                Contact oldC = (Contact) so;
                if (oldC.Id != null) {
                    oldById.put(oldC.Id, oldC);
                }
            }
        }
        validate(triggerNew, oldById);
    }

    private static void validate(List<SObject> triggerNew, Map<Id, Contact> oldById) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Set<Id> batchIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.Id != null) {
                batchIds.add(c.Id);
            }
        }

        // Records that must be checked, and unchanged records that only hold a slot.
        List<Contact> toCheck = new List<Contact>();
        List<Contact> holders = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            Boolean mustCheck = true;
            if (c.Id != null && oldById.containsKey(c.Id)) {
                Contact oldC = oldById.get(c.Id);
                mustCheck = (c.Email != oldC.Email) || (c.AccountId != oldC.AccountId);
            }

            if (mustCheck) {
                toCheck.add(c);
                accountIds.add(c.AccountId);
                emails.add(c.Email.toLowerCase());
            } else {
                holders.add(c);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // Single query. Rows that are part of this save are skipped because their
        // new values come from triggerNew.
        Set<String> storedKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email IN :emails
        ]) {
            if (batchIds.contains(existing.Id)) {
                continue;
            }
            storedKeys.add(keyOf(existing.AccountId, existing.Email));
        }

        // Unchanged records claim their slots first.
        Set<String> claimed = new Set<String>();
        for (Contact c : holders) {
            claimed.add(keyOf(c.AccountId, c.Email));
        }

        // Changed records in list order: first claimant wins, later ones are rejected.
        for (Contact c : toCheck) {
            String key = keyOf(c.AccountId, c.Email);
            if (storedKeys.contains(key) || claimed.contains(key)) {
                c.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                claimed.add(key);
            }
        }
    }

    private static String keyOf(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
```

