public class TA_Case_AddClosureComment implements TriggerAction.AfterUpdate {

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldById = new Map<Id, Case>();
        for (SObject so : triggerOld) {
            Case o = (Case) so;
            oldById.put(o.Id, o);
        }

        String commentBody = 'Case closed on ' + String.valueOf(Date.today());
        List<CaseComment> comments = new List<CaseComment>();

        for (SObject so : triggerNew) {
            Case c = (Case) so;
            Case old = oldById.get(c.Id);
            if (old != null && c.Status == 'Closed' && old.Status != 'Closed') {
                comments.add(new CaseComment(
                    ParentId = c.Id,
                    CommentBody = commentBody,
                    IsPublished = false
                ));
            }
        }

        if (!comments.isEmpty()) {
            insert comments;
        }
    }
}
