/**
 * Before insert: when a new Contact has an Account and all of its mailing
 * address fields are blank, copies the Account's billing address into them.
 * Relies on TA_Contact_Queries.Service having loaded the parent accounts.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact con = (Contact) so;

            if (con.AccountId == null || !accountsById.containsKey(con.AccountId)) {
                continue;
            }

            if (String.isNotBlank(con.MailingStreet)
                    || String.isNotBlank(con.MailingCity)
                    || String.isNotBlank(con.MailingPostalCode)
                    || String.isNotBlank(con.MailingCountry)) {
                continue;
            }

            Account parent = accountsById.get(con.AccountId);
            con.MailingStreet = parent.BillingStreet;
            con.MailingCity = parent.BillingCity;
            con.MailingPostalCode = parent.BillingPostalCode;
            con.MailingCountry = parent.BillingCountry;
        }
    }
}
